-- =====================================================================================
-- C38-01 — Formatos de ASOPREP derivados del B17, como definiciones de la empresa 1236 sobre las tablas de C19-01:
--   FLE  ESTADO DE FLUJOS DE EFECTIVO, metodo indirecto (formatos "FLUJO DE EFECTIVO_ENE_2026 FORMATO.xlsx" y
--        "FLUJO EFECTIVO_12_2025.xlsx"). Alterno 8.
--   FCD  FLUJO DE CAJA REAL, metodo directo (formato BIESS "FLUJO DE CAJA_12_2025_FORMATO.xlsx"). Alterno 9.
--   CMP  BALANCE COMPARATIVO dic. anterior vs mes con los codigos del B17 ("COMPARATIVO_01_2026_FORMATO.xlsx"). Alterno 10.
-- Cuadre Superintendencia, tarea C38 · 2026-11-19. Los genera POST /flef/generar, /flef/excel, /flef/comparativo y
-- /flef/comparativoExcel (FlujoEfectivoServiceImpl + com.saa.ejb.cnt.flujo); /esrp los rechaza (RPRTFRAR = 2).
-- Mapeo: cuadreSuper 03-trabajo/flujo-efectivo/README.md §2 (indirecto) y §3 (directo), el mismo del script
--   flujo-efectivo.js. Ver docs/logica-negocio/rpr/FLUJO-EFECTIVO-Y-COMPARATIVO.md.
--
-- Como se leen las definiciones (no hay codigos de cuenta en Java):
--   FLE  RNRPORDN = fila del formato de enero 2026 (el de diciembre va dos filas mas arriba). RNRPNVLL 0 = titulo o
--        nota, 1 = columna de totales (F), 2 = parciales (D). RNRPTPCL 1 = formula sobre CODIGOS DEL B17 con efecto en
--        caja (activo con "-", pasivo y patrimonio con "+"); RNRPBSVL 2 = variacion del periodo, 1 = saldo al corte,
--        3 = saldo a la fecha base. RNRPTPCL 3 = suma de otros renglones (subtotales, como las formulas del Excel).
--        FE10 (utilidad) y FE44 (resultados) reparten el cierre del ejercicio si el periodo cruza el 1 de enero.
--   FCD  Renglones = filas del formato BIESS; RNRPNVLL 9 = cuenta puente (no va al formato). Reglas con CRRPMDSG 1
--        (naturaleza) = cuentas del plan del SAA: destino FC10 = caja (1.1), destino PUnn = puente, CRRPRPRT 0 =
--        fuera del flujo (orden). Reglas con CRRPMDSG 3 (acreedor: entra dinero) y 2 (deudor: sale dinero) =
--        clasificacion por CODIGO DEL B17 de la cuenta final (CRRPCNTA sin puntos, prefijo; gana el mas largo).
--   CMP  Un renglon por fila del formato: RNRPCDRN = codigo de la columna CODIGO, RNRPFRML = codigos del B17 de las
--        columnas E y G, RNRPNVLL 0 = titulo. Columna H: activo = E - G; pasivo y patrimonio = G - E (rubro 250).
--        Fila 66 agregada: resultado del periodo (5 - 4), para que la columna H sume 0.
--
-- Observaciones del README que se respetan: fila 12 con 1699 y 1999 (el formato trae 1602 y "19990"); fila 34 con
--   15 y 17; fila 45 agregada (24, obligaciones financieras); FCD: mora (fila 16) y novaciones (17) en 0, historia
--   laboral (37-39) sin fuente contable, 47 (provisiones) no aparece en el directo (no es caja).
--
-- SQL PURO, SIN COMMIT. Requiere C19-01 y C19-02 (B17). Solo inserta; no toca el B17 ni el FLC provisional (C19-03).
-- =====================================================================================

-- BLOQUE 1 — CONTROL ANTES.
-- 1.1 ESPERADO: 0 filas.
SELECT RPRTCDGO, RPRTNMBR, RPRTALTR, RPRTCDES FROM CNT.RPRT WHERE PJRQCDGO = 1236 AND (RPRTCDES IN ('FLE', 'FCD', 'CMP') OR RPRTALTR IN (8, 9, 10));
-- 1.2 ESPERADO: 1 fila (el B17 de C19-02, alterno 6).
SELECT RPRTCDGO, RPRTNMBR, RPRTALTR FROM CNT.RPRT WHERE PJRQCDGO = 1236 AND RPRTCDES = 'B17' AND RPRTESTD = 1;

-- BLOQUE 2 — CABECERAS (tipo 2 = estructura; RPRTFRAR 2 = formato derivado del B17, se genera con /flef)
VALUES (CNT.SQ_RPRTCDGO.NEXTVAL, 1236, 'ESTADO DE FLUJOS DE EFECTIVO (FORMATO ASOPREP)', 1, 8, 2, 'FLE', 'M', '3968', 2, 0, 0, 2, 0, 'ESTADO DE FLUJOS DE EFECTIVO');
VALUES (CNT.SQ_RPRTCDGO.NEXTVAL, 1236, 'FLUJO DE CAJA REAL (FORMATO BIESS, METODO DIRECTO)', 1, 9, 2, 'FCD', 'M', '3968', 2, 0, 0, 2, 0, 'FORMATO FLUJO DE CAJA');
VALUES (CNT.SQ_RPRTCDGO.NEXTVAL, 1236, 'BALANCE COMPARATIVO (FORMATO ASOPREP)', 1, 10, 2, 'CMP', 'M', '3968', 1, 0, 0, 2, 0, 'BALANCE COMPARATIVO');

-- BLOQUE 3 — FLE: filas del estado de flujos de efectivo

-- BLOQUE 4 — FCD: filas del formato BIESS y cuentas puente

-- BLOQUE 5 — FCD: reglas (caja, orden, puentes y clasificacion por codigo del B17)

-- BLOQUE 6 — CMP: filas del comparativo

-- BLOQUE 7 — CONTROL DESPUES
-- 7.1 ESPERADO: FLE 35 renglones 0 reglas · FCD 35 renglones 110 reglas · CMP 61 renglones 0 reglas.
SELECT r.RPRTCDES, r.RPRTALTR, r.RPRTFRAR, (SELECT COUNT(*) FROM CNT.RNRP n WHERE n.RPRTCDGO = r.RPRTCDGO) renglones,
       (SELECT COUNT(*) FROM CNT.CRRP c WHERE c.RPRTCDGO = r.RPRTCDGO) reglas
  FROM CNT.RPRT r WHERE r.PJRQCDGO = 1236 AND r.RPRTCDES IN ('FLE', 'FCD', 'CMP') ORDER BY r.RPRTALTR;
-- 7.2 Reglas de FCD sobre cuentas del plan (CRRPMDSG 1) que no existen en el plan de la 1236. ESPERADO: 0 filas.
SELECT c.CRRPCNTA FROM CNT.CRRP c JOIN CNT.RPRT r ON r.RPRTCDGO = c.RPRTCDGO WHERE r.PJRQCDGO = 1236 AND r.RPRTCDES = 'FCD'
   AND c.CRRPMDSG = 1 AND NOT EXISTS (SELECT 1 FROM CNT.PLNN p WHERE p.PJRQCDGO = 1236 AND p.PLNNCNTA = c.CRRPCNTA);
-- 7.3 Codigos del B17 usados en FLE, CMP y en la clasificacion de FCD que no son renglones del B17. ESPERADO: 0 filas.
SELECT 'FCD' estructura, c.CRRPCNTA codigo FROM CNT.CRRP c JOIN CNT.RPRT r ON r.RPRTCDGO = c.RPRTCDGO
 WHERE r.PJRQCDGO = 1236 AND r.RPRTCDES = 'FCD' AND c.CRRPMDSG IN (2, 3)
   AND NOT EXISTS (SELECT 1 FROM CNT.RNRP b JOIN CNT.RPRT rb ON rb.RPRTCDGO = b.RPRTCDGO
                    WHERE rb.PJRQCDGO = 1236 AND rb.RPRTCDES = 'B17' AND b.RNRPCDRN = c.CRRPCNTA)
UNION ALL
SELECT r.RPRTCDES, t.codigo FROM CNT.RPRT r JOIN CNT.RNRP n ON n.RPRTCDGO = r.RPRTCDGO
 CROSS APPLY (SELECT LTRIM(LTRIM(REGEXP_SUBSTR(n.RNRPFRML, '[^ ]+', 1, LEVEL), '+'), '-') codigo FROM DUAL
              CONNECT BY REGEXP_SUBSTR(n.RNRPFRML, '[^ ]+', 1, LEVEL) IS NOT NULL) t
 WHERE r.PJRQCDGO = 1236 AND ((r.RPRTCDES = 'FLE' AND n.RNRPTPCL = 1) OR r.RPRTCDES = 'CMP') AND n.RNRPFRML IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM CNT.RNRP b JOIN CNT.RPRT rb ON rb.RPRTCDGO = b.RPRTCDGO
                    WHERE rb.PJRQCDGO = 1236 AND rb.RPRTCDES = 'B17' AND b.RNRPCDRN = t.codigo);

